diagrams.source:
flowchart TD
  Load["GET /daily/today"] --> Case{"case exists?"}
  Case -->|No|Empty["Show no puzzle"]
  Case -->|Yes|Play{"saved play exists?"}
  Play -->|No|Intro["Show case introduction"]
  Play -->|Yes|Resume["Resume play.phase"]

flowchart TD
  Input["Tap: x and y from 0 to 1"] --> State{"investigating and taps left?"}
  State -->|No|Reject["409 invalid_state"]
  State -->|Yes|Eligible{"question asked or witnesses resting?"}
  Eligible -->|No|Reject
  Eligible -->|Yes|Record["Record tap and proximity"]
  Record --> Hit{"hit or final tap?"}
  Hit -->|Yes|Accuse["phase = accusing"]
  Hit -->|No|Investigate["phase stays investigating"]

flowchart TD
  Read["GET /daily/case/{number}"] --> Exists{"known and no later than tomorrow UTC?"}
  Exists -->|No|Missing["404 not_found"]
  Exists -->|Yes|Closed{"date earlier than yesterday UTC?"}
  Closed -->|No|Open["Original image; answer fields null"]
  Closed -->|Yes|Reveal["Original and changed images; answer revealed"]
